{"name": "create_monthly_sales_summary", "query": "
-- ============================================================
-- TABLE 1: monthly_sales_summary
-- Tracks key business metrics aggregated by calendar month
-- ============================================================
CREATE TABLE public.monthly_sales_summary (
    year_month            VARCHAR(7)      NOT NULL,   -- 'YYYY-MM'
    total_invoices        INTEGER         NOT NULL,
    total_revenue         DECIMAL(10, 2)  NOT NULL,
    total_tracks_sold     INTEGER         NOT NULL,
    average_invoice_value DECIMAL(10, 2)  NOT NULL,
    unique_customers      INTEGER         NOT NULL,
    PRIMARY KEY (year_month)
);

COMMENT ON TABLE  public.monthly_sales_summary                       IS 'Monthly business performance summary derived from Chinook invoice data.';
COMMENT ON COLUMN public.monthly_sales_summary.year_month            IS 'Calendar month in YYYY-MM format (e.g. 2009-01).';
COMMENT ON COLUMN public.monthly_sales_summary.total_invoices        IS 'Number of invoices issued in the month.';
COMMENT ON COLUMN public.monthly_sales_summary.total_revenue         IS 'Sum of all invoice totals for the month.';
COMMENT ON COLUMN public.monthly_sales_summary.total_tracks_sold     IS 'Total quantity of individual track line-items sold.';
COMMENT ON COLUMN public.monthly_sales_summary.average_invoice_value IS 'Mean invoice value for the month.';
COMMENT ON COLUMN public.monthly_sales_summary.unique_customers      IS 'Count of distinct customers who purchased in the month.';
"}

{"name": "create_top_music_charts", "query": "
-- ============================================================
-- TABLE 2: top_music_charts
-- All-time top-10 rankings for tracks, albums, and artists
-- ============================================================
CREATE TABLE public.top_music_charts (
    chart_type    VARCHAR(20)     NOT NULL,   -- 'top_tracks' | 'top_albums' | 'top_artists'
    rank_position INTEGER         NOT NULL,   -- 1–10
    item_id       INTEGER         NOT NULL,
    item_name     VARCHAR(255)    NOT NULL,
    total_revenue DECIMAL(10, 2)  NOT NULL,
    PRIMARY KEY (chart_type, rank_position),
    CONSTRAINT chk_chart_type    CHECK (chart_type    IN ('top_tracks', 'top_albums', 'top_artists')),
    CONSTRAINT chk_rank_position CHECK (rank_position BETWEEN 1 AND 10)
);

COMMENT ON TABLE  public.top_music_charts              IS 'All-time top-10 charts for tracks, albums, and artists based on revenue.';
COMMENT ON COLUMN public.top_music_charts.chart_type    IS 'Chart category: top_tracks, top_albums, or top_artists.';
COMMENT ON COLUMN public.top_music_charts.rank_position IS 'Rank within the chart (1 = best seller).';
COMMENT ON COLUMN public.top_music_charts.item_id       IS 'Primary key of the ranked entity in its source table.';
COMMENT ON COLUMN public.top_music_charts.item_name     IS 'Display name of the track, album, or artist.';
COMMENT ON COLUMN public.top_music_charts.total_revenue IS 'Total revenue attributed to this item.';
"}

